// Eventos del calendario recibidos del nodo anterior
const events = $input.all().map(item => item.json);

// Datos originales del formulario
const form = $('Webhook Formulario').first().json.body;
const lang = form.idioma || 'es';
const isEN = lang === 'en';

// ⚙️ Ajustar zona horaria según tu región
const TZ = 'America/Bogota';
const SLOT_MS = 3600000; // 1 hora en ms

// Construir períodos ocupados desde eventos del calendario
const busy = events
  .filter(ev => ev.start)
  .map(ev => ({
    start: new Date(ev.start.dateTime || ev.start.date + 'T00:00:00'),
    end:   new Date(ev.end.dateTime   || ev.end.date   + 'T23:59:59')
  }));

// Buscar 3 slots libres: Lunes-Viernes 9:00–17:00, próximos 21 días
const slots = [];
const c = new Date();
c.setMinutes(0, 0, 0);
c.setHours(c.getHours() + 1);
const cutoff = new Date(Date.now() + 21 * 24 * 3600000);

while (c < cutoff && slots.length < 3) {
  const day  = c.getDay();
  const hour = c.getHours();

  // Saltar fines de semana
  if (day === 0 || day === 6) {
    c.setDate(c.getDate() + (day === 0 ? 1 : 2));
    c.setHours(9, 0, 0, 0);
    continue;
  }

  // Ajustar a horario laboral
  if (hour < 9)  { c.setHours(9, 0, 0, 0); continue; }
  if (hour >= 17) { c.setDate(c.getDate() + 1); c.setHours(9, 0, 0, 0); continue; }

  const slotEnd = new Date(c.getTime() + SLOT_MS);
  const conflict = busy.some(b => c < b.end && slotEnd > b.start);

  if (!conflict) {
    slots.push({
      es: c.toLocaleString('es-ES', {
        weekday: 'long', day: 'numeric', month: 'long',
        hour: '2-digit', minute: '2-digit', timeZone: TZ
      }),
      en: c.toLocaleString('en-US', {
        weekday: 'long', month: 'long', day: 'numeric',
        hour: '2-digit', minute: '2-digit', timeZone: TZ
      })
    });
    c.setTime(slotEnd.getTime());
  } else {
    c.setHours(c.getHours() + 1);
  }
}

// Preparar HTML del email
const lbl = s => isEN ? s.en : s.es;

const noSlotsMsg = isEN
  ? 'Our team will contact you directly to schedule a meeting.'
  : 'Nuestro equipo te contactará directamente para coordinar un horario.';

const slotsHtml = slots.length
  ? slots.map((s, i) => `<li style='margin:0 0 10px;padding:12px 16px;background:#F9F9F8;border-left:3px solid #111111;list-style:none;font-size:14px;color:#111111;'><b>Opci&#243;n ${i + 1}:</b> ${lbl(s)}</li>`).join('')
  : `<li style='list-style:none;font-size:14px;color:#767676;'>${noSlotsMsg}</li>`;

const emailSubject = isEN
  ? 'We received your message \u2014 SISTEG'
  : 'Recibimos tu mensaje \u2014 SISTEG';

const intro1 = isEN
  ? `Thank you for contacting SISTEG. We have received your message and our team will review it shortly.`
  : `Gracias por contactar a SISTEG. Hemos recibido tu mensaje y nuestro equipo lo revisar&#225; a la brevedad.`;

const intro2 = isEN
  ? `To schedule our first conversation, here are <b>3 available time slots</b>:`
  : `Para agendar nuestra primera conversaci&#243;n, aqu&#237; tienes <b>3 opciones de horario disponibles</b>:`;

const closing1 = isEN
  ? `Simply reply to this email with your preferred time, or suggest an alternative that works better for you.`
  : `Solo responde este correo indicando qu&#233; horario te viene mejor, o sug&#237;ere una alternativa.`;

const closingName = isEN ? 'Best regards,' : 'Saludos cordiales,';
const greeting   = isEN ? 'Hello' : 'Hola';

const emailHtml = `<!DOCTYPE html><html lang='${lang}'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;padding:0;background:#FBFBFA;font-family:Arial,Helvetica,sans-serif;'><table width='100%' cellpadding='0' cellspacing='0' style='background:#FBFBFA;'><tr><td align='center' style='padding:40px 20px;'><table width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF;border:1px solid #EAEAEA;max-width:580px;'><tr><td style='padding:26px 36px;border-bottom:2px solid #111111;'><span style='font-size:19px;font-family:Georgia,serif;font-weight:600;color:#111111;letter-spacing:-.01em;'>SISTEG</span></td></tr><tr><td style='padding:36px 36px 0;'><p style='font-size:16px;color:#111111;margin:0 0 16px;'>${greeting} <b>${form.nombre}</b>,</p><p style='font-size:14px;color:#444444;line-height:1.75;margin:0 0 20px;'>${intro1}</p><p style='font-size:14px;color:#444444;line-height:1.75;margin:0 0 14px;'>${intro2}</p><ul style='padding:0;margin:0 0 24px;'>${slotsHtml}</ul><p style='font-size:14px;color:#444444;line-height:1.75;margin:0 0 32px;'>${closing1}</p><hr style='border:none;border-top:1px solid #EAEAEA;margin:0 0 24px;'><p style='font-size:14px;color:#444444;margin:0 0 4px;'>${closingName}<br><b>Equipo SISTEG</b></p><a href='mailto:info@sisteg.net' style='font-size:13px;color:#767676;text-decoration:none;'>info@sisteg.net</a></td></tr><tr><td style='padding:18px 36px;background:#F9F9F8;border-top:1px solid #EAEAEA;'><p style='font-size:11px;color:#AAAAAA;margin:0;'>&copy; 2025 SISTEG &middot; Latinoam&eacute;rica &amp; United States</p></td></tr></table></td></tr></table></body></html>`;

return [{ json: { ...form, slots, emailSubject, emailHtml } }];
